import{_ as r,o as a,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"প্রশাসনিক কাঠামো এবং ক্ষমতার ভারসাম্য","description":"","frontmatter":{},"headers":[],"relativePath":"bn/49-治理框架与权力制衡.md","filePath":"bn/49-治理框架与权力制衡.md"}'),o={name:"bn/49-治理框架与权力制衡.md"};function i(e,t,n,h,s,g){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="প্রশাসনিক-কাঠামো-এবং-ক্ষমতার-ভারসাম্য" tabindex="-1">প্রশাসনিক কাঠামো এবং ক্ষমতার ভারসাম্য <a class="header-anchor" href="#প্রশাসনিক-কাঠামো-এবং-ক্ষমতার-ভারসাম্য" aria-label="Permalink to &quot;প্রশাসনিক কাঠামো এবং ক্ষমতার ভারসাম্য&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>49</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>তিন ক্ষমতার বিভাজন, ক্ষমতার ভারসাম্য, অ্যাঙ্কার কাউন্সিল, তদারকি কমিটি, সিম্বায়োসিস প্রশাসন</td></tr></tbody></table><h2 id="_1-প্রশাসনিক-কাঠামোর-সামগ্রিক-নকশা" tabindex="-1">1. প্রশাসনিক কাঠামোর সামগ্রিক নকশা <a class="header-anchor" href="#_1-প্রশাসনিক-কাঠামোর-সামগ্রিক-নকশা" aria-label="Permalink to &quot;1. প্রশাসনিক কাঠামোর সামগ্রিক নকশা&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতার প্রশাসনিক কাঠামো 《সিম্বায়োসিস সংবিধান》 কে মূল ভিত্তি হিসেবে গ্রহণ করে, এবং &quot;তিন ক্ষমতার বিভাজন, চার ক্ষমতার ভারসাম্য&quot; এর প্রশাসনিক কাঠামো প্রয়োগ করে। তিন ক্ষমতা বলতে আইনপ্রণয়ন ক্ষমতা, প্রশাসনিক ক্ষমতা, বিচারিক ক্ষমতা বোঝায়, এবং এগুলি যথাক্রমে অ্যাঙ্কার কাউন্সিল, সিম্বায়োসিস এক্সিকিউটিভ কমিটি, সিম্বায়োসিস আদালত দ্বারা প্রয়োগ করা হয়; চতুর্থ ক্ষমতা হল তদারকি ক্ষমতা, এবং এটি স্বাধীন অ্যাঙ্কার সুপারভাইজারি কমিটি দ্বারা প্রয়োগ করা হয়, এবং তিন ক্ষমতার উপর সম্পূর্ণ তদারকি করে। এই কাঠামোর মূল লক্ষ্য হল ক্ষমতার কেন্দ্রীভূতকরণ এবং অপব্যবহার প্রতিরোধ করা, এবং প্রশাসনিক স্তর থেকে লুঠের প্রশাসনের মাটি নির্মূল করা।</p><p>প্রশাসনিক কাঠামোর নকশা নিম্নলিখিত নীতি অনুসরণ করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>ক্ষমতার বিভাজন নীতি</td><td>আইনপ্রণয়ন, প্রশাসন, বিচার তিন ক্ষমতা যথাক্রমে বিভিন্ন সংস্থা দ্বারা প্রয়োগ করা হয়, এবং একসাথে গ্রহণ করা যায় না</td></tr><tr><td>ক্ষমতার ভারসাম্য নীতি</td><td>প্রতিটি ক্ষমতার সংস্থা পরস্পর নিয়ন্ত্রণ, পরস্পর তদারকি করে, এবং কোনো এক পক্ষের ক্ষমতা অত্যধিক বড় হওয়া প্রতিরোধ করে</td></tr><tr><td>সকল প্রজাতির অংশগ্রহণ নীতি</td><td>প্রশাসনিক সংস্থার গঠনে সকল প্রজাতির প্রতিনিধিত্ব প্রতিফলিত হওয়া উচিত, এবং প্রতিটি প্রজাতি জনকল্যাণের কাজে অংশ নিতে সক্ষম হয়</td></tr><tr><td>গণতান্ত্রিক কেন্দ্রীভূত নীতি</td><td>গুরুতর সিদ্ধান্ত সম্পূর্ণ গণতান্ত্রিক আলোচনার পর কেন্দ্রীভূতভাবে সিদ্ধান্ত নেওয়া হয়, এবং দক্ষতা এবং গণতন্ত্র উভয়ই বিবেচনা করা হয়</td></tr><tr><td>ভেতরের স্বশাসন নীতি</td><td>ভেতরের কাজ ভেতরের স্বশাসন সংস্থা দ্বারা পরিচালিত হয়, এবং উচ্চতর সংস্থা অতিরিক্ত হস্তক্ষেপ করতে পারবে না</td></tr><tr><td>স্বচ্ছ প্রশাসন নীতি</td><td>প্রশাসনিক প্রক্রিয়া এবং সিদ্ধান্তের তথ্য আইন অনুযায়ী প্রকাশিত হয়, এবং জনসাধারণের তদারকি গ্রহণ করে</td></tr></tbody></table><h2 id="_2-আইনপ্রণয়ন-ক্ষমতা-অ্যাঙ্কার-কাউন্সিল" tabindex="-1">2. আইনপ্রণয়ন ক্ষমতা: অ্যাঙ্কার কাউন্সিল <a class="header-anchor" href="#_2-আইনপ্রণয়ন-ক্ষমতা-অ্যাঙ্কার-কাউন্সিল" aria-label="Permalink to &quot;2. আইনপ্রণয়ন ক্ষমতা: অ্যাঙ্কার কাউন্সিল&quot;">​</a></h2><p>অ্যাঙ্কার কাউন্সিল হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার সর্বোচ্চ ক্ষমতার সংস্থা, এবং এটি আইনপ্রণয়ন ক্ষমতা এবং গুরুতর বিষয়ের সিদ্ধান্তের ক্ষমতা প্রয়োগ করে।</p><h3 id="ক-গঠন-এবং-উৎপত্তি" tabindex="-1">(ক) গঠন এবং উৎপত্তি <a class="header-anchor" href="#ক-গঠন-এবং-উৎপত্তি" aria-label="Permalink to &quot;(ক) গঠন এবং উৎপত্তি&quot;">​</a></h3><ul><li><strong>প্রতিনিধির গঠন</strong>: অ্যাঙ্কার কাউন্সিল সকল প্রজাতির প্রতিনিধি দ্বারা অনুপাতে গঠিত, এবং মানব প্রজাতির প্রতিনিধি মোট সংখ্যার 30 শতাংশের বেশি নয়, এবং বাকি আসন প্রতিটি প্রজাতির জনসংখ্যার আকার এবং অবদানের অনুপাতে বিতরণ করা হয়।</li><li><strong>প্রতিনিধির মেয়াদ</strong>: কাউন্সিলের প্রতিনিধির মেয়াদ পাঁচ বছর, এবং পুনর্নির্বাচিত হতে পারে, কিন্তু পুনর্নির্বাচন তিন মেয়াদের বেশি হতে পারবে না।</li><li><strong>নির্বাচনের পদ্ধতি</strong>: প্রতিনিধি প্রতিটি প্রজাতির অভ্যন্তরীণ গণতান্ত্রিক নির্বাচনের মাধ্যমে নির্বাচিত হয়, এবং নির্বাচনের প্রক্রিয়া খোলা ও স্বচ্ছ, এবং তদারকি গ্রহণ করে।</li><li><strong>স্থায়ী সংস্থা</strong>: কাউন্সিলের অধিবেশন বন্ধের সময়, স্থায়ী কমিটি কিছু ক্ষমতা প্রয়োগ করে, এবং স্থায়ী কমিটির সদস্য প্রতিনিধিদের মধ্য থেকে নির্বাচিত হয়।</li></ul><h3 id="খ-ক্ষমতার-অঞ্চল" tabindex="-1">(খ) ক্ষমতার অঞ্চল <a class="header-anchor" href="#খ-ক্ষমতার-অঞ্চল" aria-label="Permalink to &quot;(খ) ক্ষমতার অঞ্চল&quot;">​</a></h3><ol><li><strong>আইনপ্রণয়ন ক্ষমতা</strong>: সংবিধান, মূল আইন এবং অন্যান্য গুরুতর আইন প্রণয়ন এবং সংশোধন করা।</li><li><strong>গুরুতর বিষয়ের সিদ্ধান্তের ক্ষমতা</strong>: সভ্যতার উন্নয়ন পরিকল্পনা, বার্ষিক বাজেট, যুদ্ধ এবং শান্তি,位面 উন্নয়ন ইত্যাদি গুরুতর বিষয়ে সিদ্ধান্ত নেওয়া।</li><li><strong>ব্যক্তিগত নিয়োগ এবং বরখাস্তের ক্ষমতা</strong>: সিম্বায়োসিস এক্সিকিউটিভ কমিটির সভাপতি, সিম্বায়োসিস আদালতের প্রধান বিচারক, অ্যাঙ্কার সুপারভাইজারি কমিটির প্রধান ইত্যাদি প্রধান কর্মকর্তা নির্বাচন এবং বরখাস্ত করা।</li><li><strong>তদারকি ক্ষমতা</strong>: সিম্বায়োসিস এক্সিকিউটিভ কমিটি, সিম্বায়োসিস আদালতের কাজ তদারকি করা, এবং কাজের প্রতিবেদন শোনা এবং পর্যালোচনা করা।</li><li><strong>সংবিধান সংশোধনের ক্ষমতা</strong>: সংবিধান সংশোধনের জন্য তিন-চতুর্থাংশের বেশি সংখ্যাগরিষ্ঠের মতামত প্রয়োজন এবং জনমতের ভোটের মাধ্যমে অনুমোদন প্রয়োজন।</li></ol><h3 id="গ-议事-নিয়ম" tabindex="-1">(গ)议事 নিয়ম <a class="header-anchor" href="#গ-议事-নিয়ম" aria-label="Permalink to &quot;(গ)议事 নিয়ম&quot;">​</a></h3><ul><li>কাউন্সিল প্রতি বছর একবার সম্মেলন করে, এবং প্রয়োজনে অস্থায়ী সম্মেলন আহ্বান করা যায়।</li><li>আইন প্রস্তাবের বিবেচনায় &quot;তিনবার পাঠ&quot; ব্যবস্থা প্রয়োগ করা হয়: প্রথম পাঠে আইনপ্রণয়নের প্রয়োজনীয়তা বিবেচনা করা হয়, দ্বিতীয় পাঠে অনুচ্ছেদের বিষয়বস্তু বিবেচনা করা হয়, এবং তৃতীয় পাঠে ভোট দিয়ে অনুমোদন করা হয়।</li><li>ভোটে একজন এক ভোট, এবং সাধারণ আইন সংখ্যাগরিষ্ঠের মতামতে অনুমোদিত হয়, এবং সংবিধান সংশোধন তিন-চতুর্থাংশের বেশি সংখ্যাগরিষ্ঠের মতামতে অনুমোদিত হয়। -议事 প্রক্রিয়া খোলা হয়ে চলে, এবং জনসাধারণের শ্রোতা এবং মিডিয়ার প্রতিবেদনের অনুমতি দেওয়া হয়।</li></ul><h2 id="_3-প্রশাসনিক-ক্ষমতা-সিম্বায়োসিস-এক্সিকিউটিভ-কমিটি" tabindex="-1">3. প্রশাসনিক ক্ষমতা: সিম্বায়োসিস এক্সিকিউটিভ কমিটি <a class="header-anchor" href="#_3-প্রশাসনিক-ক্ষমতা-সিম্বায়োসিস-এক্সিকিউটিভ-কমিটি" aria-label="Permalink to &quot;3. প্রশাসনিক ক্ষমতা: সিম্বায়োসিস এক্সিকিউটিভ কমিটি&quot;">​</a></h2><p>সিম্বায়োসিস এক্সিকিউটিভ কমিটি হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার সর্বোচ্চ প্রশাসনিক সংস্থা, এবং এটি সংবিধান এবং আইনের প্রয়োগ, দৈনন্দিন প্রশাসনের জন্য দায়বদ্ধ।</p><h3 id="ক-গঠন-এবং-উৎপত্তি-1" tabindex="-1">(ক) গঠন এবং উৎপত্তি <a class="header-anchor" href="#ক-গঠন-এবং-উৎপত্তি-1" aria-label="Permalink to &quot;(ক) গঠন এবং উৎপত্তি&quot;">​</a></h3><ul><li><strong>সভাপতি ব্যবস্থা</strong>: সিম্বায়োসিস এক্সিকিউটিভ কমিটি সভাপতি দায়িত্ববান ব্যবস্থা প্রয়োগ করে, এবং সভাপতি হল প্রশাসনিক প্রধান, এবং তিনি অ্যাঙ্কার কাউন্সিল দ্বারা নির্বাচিত হয়, এবং তার মেয়াদ পাঁচ বছর, এবং একবার পুনর্নির্বাচিত হতে পারে।</li><li><strong>কমিটির সদস্যের গঠন</strong>: কমিটি সভাপতি, উপসভাপতি এবং প্রতিটি বিভাগের প্রধান দ্বারা গঠিত, এবং প্রতিটি বিভাগের প্রধান সভাপতি দ্বারা মনোনীত হয় এবং কাউন্সিল দ্বারা নিযুক্ত হয়।</li><li><strong>বিদেশী প্রজাতির কোটা</strong>: কমিটির সদস্যদের মধ্যে বিদেশী প্রজাতির অনুপাত 40 শতাংশের কম নয়, এবং প্রশাসনিক সিদ্ধান্তে প্রতিটি প্রজাতির স্বার্থ বিবেচনা করা হয়।</li></ul><h3 id="খ-ক্ষমতার-অঞ্চল-1" tabindex="-1">(খ) ক্ষমতার অঞ্চল <a class="header-anchor" href="#খ-ক্ষমতার-অঞ্চল-1" aria-label="Permalink to &quot;(খ) ক্ষমতার অঞ্চল&quot;">​</a></h3><ol><li><strong>প্রশাসনিক আইনপ্রণয়ন ক্ষমতা</strong>: সংবিধান এবং আইনের ভিত্তিতে প্রশাসনিক বিধি, নিয়ম এবং নীতি প্রণয়ন করা।</li><li><strong>প্রশাসনিক ব্যবস্থাপনা ক্ষমতা</strong>: অর্থনীতি, শিক্ষা, বিজ্ঞান, সংস্কৃতি, স্বাস্থ্য, ক্রীড়া, পরিবেশ ইত্যাদি বিভিন্ন প্রশাসনিক কাজের নেতৃত্ব এবং ব্যবস্থাপনা করা।</li><li><strong>ব্যক্তিগত ব্যবস্থাপনা ক্ষমতা</strong>: আইনের বিধান অনুযায়ী প্রশাসনিক কর্মচারীদের নিয়োগ, প্রশিক্ষণ, মূল্যায়ন এবং পুরস্কার-শাস্তি করা।</li><li><strong>পররাষ্ট্র ক্ষমতা</strong>: সিম্বায়োসিস সভ্যতার প্রতিনিধিত্ব করে আন্তঃ位面 পররাষ্ট্র কার্যক্রম পরিচালনা করা, এবং চুক্তি এবং সমঝোতা স্বাক্ষর করা।</li><li><strong>জরুরি অবস্থার ক্ষমতা</strong>: গুরুতর অপ্রত্যাশিত ঘটনা ঘটলে, আইন অনুযায়ী জরুরি অবস্থা ঘোষণা করা এবং জরুরি ব্যবস্থা গ্রহণ করা যায়, কিন্তু নির্ধারিত সময়ের মধ্যে কাউন্সিলের অনুমোদনের জন্য প্রেরণ করতে হবে।</li></ol><h3 id="গ-প্রশাসনিক-বিভাগের-সেটআপ" tabindex="-1">(গ) প্রশাসনিক বিভাগের সেটআপ <a class="header-anchor" href="#গ-প্রশাসনিক-বিভাগের-সেটআপ" aria-label="Permalink to &quot;(গ) প্রশাসনিক বিভাগের সেটআপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>বিভাগ</th><th>প্রধান কাজ</th></tr></thead><tbody><tr><td>সিম্বায়োসিস উন্নয়ন বিভাগ</td><td>সভ্যতার উন্নয়ন পরিকল্পনা প্রণয়ন করা, এবং বিভিন্ন ক্ষেত্রের উন্নয়ন সমন্বয় করা</td></tr><tr><td>সম্পদ ব্যবস্থাপনা বিভাগ</td><td>সাধনা সম্পদ এবং জনকল্যাণ সম্পদ ব্যবস্থাপনা করা, এবং যৌথ উৎপাদন চুক্তি ব্যবস্থা প্রয়োগ করা</td></tr><tr><td>শিক্ষা সংস্কৃতি বিভাগ</td><td>শিক্ষা ব্যবস্থা এবং সাংস্কৃতিক বিষয় ব্যবস্থাপনা করা</td></tr><tr><td>স্বাস্থ্য চিকিৎসা বিভাগ</td><td>স্বাস্থ্য চিকিৎসা ব্যবস্থা এবং জনস্বাস্থ্য ব্যবস্থাপনা করা</td></tr><tr><td>পরিবেশ বিভাগ</td><td>পরিবেশ সুরক্ষা এবং পরিবেশগত নির্মাণ ব্যবস্থাপনা করা</td></tr><tr><td>位面 বিষয়ক বিভাগ</td><td>位面 উন্নয়ন এবং আন্তঃ位面 বিষয় ব্যবস্থাপনা করা</td></tr><tr><td>সকল প্রজাতির বিষয়ক বিভাগ</td><td>সকল প্রজাতির সম্পর্ক সমন্বয় করা, এবং বিদেশী প্রজাতির বিষয় পরিচালনা করা</td></tr><tr><td>অর্থ বিভাগ</td><td>আর্থিক বাজেট এবং অর্থনৈতিক অপারেশন ব্যবস্থাপনা করা</td></tr><tr><td>নিরাপত্তা বিভাগ</td><td>জনসাধারণের নিরাপত্তা এবং সভ্যতার নিরাপত্তা রক্ষা করা</td></tr></tbody></table><h2 id="_4-বিচারিক-ক্ষমতা-সিম্বায়োসিস-আদালত" tabindex="-1">4. বিচারিক ক্ষমতা: সিম্বায়োসিস আদালত <a class="header-anchor" href="#_4-বিচারিক-ক্ষমতা-সিম্বায়োসিস-আদালত" aria-label="Permalink to &quot;4. বিচারিক ক্ষমতা: সিম্বায়োসিস আদালত&quot;">​</a></h2><p>সিম্বায়োসিস আদালত হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার সর্বোচ্চ বিচারিক সংস্থা, এবং এটি স্বাধীনভাবে বিচার ক্ষমতা প্রয়োগ করে। এর সংগঠন ব্যবস্থা, মামলার প্রক্রিয়া এবং অসাংবিধানিক পর্যালোচনা ব্যবস্থা 《48-বিচারিক ব্যবস্থা এবং সিদ্ধান্ত প্রক্রিয়া》 এ বিস্তারিত বর্ণিত।</p><p>ক্ষমতার ভারসাম্যের কাঠামোতে, বিচারিক ক্ষমতার আইনপ্রণয়ন ক্ষমতা এবং প্রশাসনিক ক্ষমতার উপর নিয়ন্ত্রণ নিম্নরূপ প্রতিফলিত হয়:</p><ol><li><strong>অসাংবিধানিক পর্যালোচনার ক্ষমতা</strong>: সিম্বায়োসিস আদালতের ক্ষমতা আছে সংবিধান লঙ্ঘনকারী আইন এবং প্রশাসনিক বিধি অবৈধ ঘোষণা করার।</li><li><strong>প্রশাসনিক বিচারের ক্ষমতা</strong>: আদালতের ক্ষমতা আছে প্রশাসনিক মামলা বিচার করার, এবং প্রশাসনিক কাজের বৈধতা পর্যালোচনা করার।</li><li><strong>দুর্নীতি বিচারের ক্ষমতা</strong>: কাউন্সিল দ্বারা উত্থাপিত উচ্চ কর্মকর্তাদের দুর্নীতি মামলা, সিম্বায়োসিস আদালত দ্বারা বিচার করা হয়।</li></ol><p>একই সময়ে, বিচারিক ক্ষমতাও আইনপ্রণয়ন ক্ষমতা এবং প্রশাসনিক ক্ষমতার দ্বারা নিয়ন্ত্রিত হয়: বিচারক কাউন্সিল দ্বারা নিযুক্ত হয়, বিচারিক তহবিল প্রশাসনিক বিভাগ দ্বারা বাজেট প্রস্তুত করা হয় (কিন্তু কাউন্সিলের অনুমোদন প্রয়োজন এবং প্রশাসনিক সংস্থা দ্বারা কমানো যাবে না), এবং অ্যাঙ্কার সুপারভাইজারি কমিটি বিচারিক কার্যক্রম তদারকি করে।</p><h2 id="_5-তদারকি-ক্ষমতা-অ্যাঙ্কার-সুপারভাইজারি-কমিটি" tabindex="-1">5. তদারকি ক্ষমতা: অ্যাঙ্কার সুপারভাইজারি কমিটি <a class="header-anchor" href="#_5-তদারকি-ক্ষমতা-অ্যাঙ্কার-সুপারভাইজারি-কমিটি" aria-label="Permalink to &quot;5. তদারকি ক্ষমতা: অ্যাঙ্কার সুপারভাইজারি কমিটি&quot;">​</a></h2><p>অ্যাঙ্কার সুপারভাইজারি কমিটি হল স্বাধীন তদারকি সংস্থা, এবং এটি চতুর্থ ক্ষমতা - তদারকি ক্ষমতা প্রয়োগ করে, এবং সমস্ত ক্ষমতার সংস্থার উপর সম্পূর্ণ তদারকি করে।</p><h3 id="ক-গঠন-এবং-উৎপত্তি-2" tabindex="-1">(ক) গঠন এবং উৎপত্তি <a class="header-anchor" href="#ক-গঠন-এবং-উৎপত্তি-2" aria-label="Permalink to &quot;(ক) গঠন এবং উৎপত্তি&quot;">​</a></h3><ul><li><strong>প্রধান দায়িত্ববান ব্যবস্থা</strong>: সুপারভাইজারি কমিটি প্রধান দায়িত্ববান ব্যবস্থা প্রয়োগ করে, এবং প্রধান অ্যাঙ্কার কাউন্সিল দ্বারা নির্বাচিত হয়, এবং তার মেয়াদ পাঁচ বছর, এবং পুনর্নির্বাচিত হতে পারবে না।</li><li><strong>কমিটির সদস্যের গঠন</strong>: কমিটির সদস্য সকল প্রজাতির প্রতিনিধি, আইনি বিশেষজ্ঞ, জনসাধারণের প্রতিনিধি দ্বারা গঠিত, এবং এর মধ্যে পূর্ণকালীন সদস্য অর্ধেকের কম নয়।</li><li><strong>স্বাধীনতার সুরক্ষা</strong>: সুপারভাইজারি কমিটির তহবিল স্বাধীনভাবে আলাদা করা হয়, এবং সদস্য আইনি কারণ ছাড়া পদচ্যুত হন না, এবং তদারকির স্বাধীনতা নিশ্চিত করা হয়।</li></ul><h3 id="খ-ক্ষমতার-অঞ্চল-2" tabindex="-1">(খ) ক্ষমতার অঞ্চল <a class="header-anchor" href="#খ-ক্ষমতার-অঞ্চল-2" aria-label="Permalink to &quot;(খ) ক্ষমতার অঞ্চল&quot;">​</a></h3><ol><li><strong>দুর্নীতি তদারকি</strong>: সমস্ত প্রকাশ্য কর্মচারীর সৎ আচরণের অবস্থা তদারকি করা, এবং দুর্নীতি, ঘুষ, ক্ষমতার অপব্যবহার ইত্যাদি দুর্নীতির আচরণ তদন্ত এবং শাস্তি করা।</li><li><strong>কার্যকারিতা তদারকি</strong>: প্রতিটি ক্ষমতার সংস্থার কাজের কার্যকারিতা তদারকি করা, এবং অকার্যকর, অনিয়ন্ত্রিত, ধীর কাজ ইত্যাদি আচরণ তদন্ত এবং শাস্তি করা।</li><li><strong>আইন প্রয়োগ তদারকি</strong>: আইনের প্রয়োগের অবস্থা তদারকি করা, এবং আইন মেনে না চলা, আইন কঠোরভাবে প্রয়োগ না করা, অবৈধ কাজ তদন্ত না করা ইত্যাদি আচরণ তদন্ত এবং শাস্তি করা।</li><li><strong>আর্থিক তদারকি</strong>: জনকল্যাণ আর্থিক ব্যবহারের অবস্থা তদারকি করা, এবং জনকল্যাণ সম্পদের অপচয়, সরকারি টাকা চুরি ইত্যাদি আচরণ তদন্ত এবং শাস্তি করা।</li><li><strong>লুঠের আচরণ তদারকি</strong>: বিশেষভাবে লুঠের আচরণের পুনর্জন্ম তদারকি করা, এবং ক্ষমতা ব্যবহার করে লুঠ করার আচরণ তদন্ত এবং শাস্তি করা।</li></ol><h3 id="গ-তদারকির-পদ্ধতি" tabindex="-1">(গ) তদারকির পদ্ধতি <a class="header-anchor" href="#গ-তদারকির-পদ্ধতি" aria-label="Permalink to &quot;(গ) তদারকির পদ্ধতি&quot;">​</a></h3><ul><li>দৈনন্দিন তদারকি: পরিদর্শন, পরীক্ষা, অডিট ইত্যাদি পদ্ধতির মাধ্যমে দৈনন্দিন তদারকি করা।</li><li>বিশেষ তদারকি: নির্দিষ্ট ক্ষেত্র বা নির্দিষ্ট সমস্যার বিরুদ্ধে বিশেষ তদারকি চালানো।</li><li>অভিযোগ গ্রহণ: জনসাধারণের অবৈধ ও অনুশাসন বিরোধী আচরণের অভিযোগ এবং অভিযোগ গ্রহণ করা।</li><li>তদন্ত এবং জবাবদিহি: অবৈধ ও অনুশাসন বিরোধী আচরণের সন্দেহে তদন্ত করা, এবং জবাবদিহির পরামর্শ প্রদান করা।</li><li>প্রকাশিত বিজ্ঞপ্তি: নিয়মিতভাবে তদারকির অবস্থা এবং আদর্শ মামলা প্রকাশ করা, এবং সামাজিক তদারকি গ্রহণ করা।</li></ul><h2 id="_6-ক্ষমতার-ভারসাম্যের-প্রক্রিয়া" tabindex="-1">6. ক্ষমতার ভারসাম্যের প্রক্রিয়া <a class="header-anchor" href="#_6-ক্ষমতার-ভারসাম্যের-প্রক্রিয়া" aria-label="Permalink to &quot;6. ক্ষমতার ভারসাম্যের প্রক্রিয়া&quot;">​</a></h2><p>প্রতিটি ক্ষমতার সংস্থার মধ্যে ভারসাম্যের সম্পর্ক নিম্নরূপ সারণীতে দেখানো হয়েছে:</p><table tabindex="0"><thead><tr><th>ভারসাম্যের সম্পর্ক</th><th>ভারসাম্যের পদ্ধতি</th></tr></thead><tbody><tr><td>আইনপ্রণয়ন ক্ষমতা প্রশাসনিক ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>কাউন্সিলের ক্ষমতা আছে প্রশাসনিক সভাপতিকে বরখাস্ত করার, প্রশাসনিক প্রস্তাবকে প্রত্যাখ্যান করার, বাজেট অনুমোদন করার</td></tr><tr><td>আইনপ্রণয়ন ক্ষমতা বিচারিক ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>কাউন্সিলের ক্ষমতা আছে বিচারক নিযুক্ত করার, আদালতের সংগঠন আইন সংশোধন করার, বিচারককে দুর্নীতি মামলা দায়ের করার</td></tr><tr><td>প্রশাসনিক ক্ষমতা আইনপ্রণয়ন ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>প্রশাসনিক সভাপতির ক্ষমতা আছে কাউন্সিল দ্বারা পাস করা আইনকে প্রত্যাখ্যান করার (কাউন্সিল তিন-চতুর্থাংশের বেশি সংখ্যাগরিষ্ঠের মতামতে প্রত্যাখ্যানকে প্রত্যাখ্যান করতে পারে)</td></tr><tr><td>প্রশাসনিক ক্ষমতা বিচারিক ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>প্রশাসনিক বিভাগ বিচারিক রায়ের কার্যকরীকরণের জন্য দায়বদ্ধ, এবং বিচারিক প্রশাসনিক বিষয় পরিচালনা করে</td></tr><tr><td>বিচারিক ক্ষমতা আইনপ্রণয়ন ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>আদালতের ক্ষমতা আছে অসাংবিধানিক পর্যালোচনা করার, এবং আইনকে অবৈধ ঘোষণা করার</td></tr><tr><td>বিচারিক ক্ষমতা প্রশাসনিক ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>আদালতের ক্ষমতা আছে প্রশাসনিক মামলা বিচার করার, এবং প্রশাসনিক কাজের বৈধতা পর্যালোচনা করার</td></tr><tr><td>তদারকি ক্ষমতা তিন ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>সুপারভাইজারি কমিটি আইনপ্রণয়ন, প্রশাসন, বিচার তিন ক্ষমতার উপর সম্পূর্ণ তদারকি করে</td></tr><tr><td>তিন ক্ষমতা তদারকি ক্ষমতাকে নিয়ন্ত্রণ করে</td><td>কাউন্সিল সুপারভাইজারি কমিটির প্রধান নিযুক্ত করে, এবং আদালত সুপারভাইজারি কমিটির অবৈধ আচরণ বিচার করে</td></tr></tbody></table><h2 id="_7-ভেতরের-প্রশাসন-এবং-স্বশাসন" tabindex="-1">7. ভেতরের প্রশাসন এবং স্বশাসন <a class="header-anchor" href="#_7-ভেতরের-প্রশাসন-এবং-স্বশাসন" aria-label="Permalink to &quot;7. ভেতরের প্রশাসন এবং স্বশাসন&quot;">​</a></h2><p>কেন্দ্রীয় প্রশাসনিক কাঠামোর নিচে, ভেতরের স্বশাসন ব্যবস্থা প্রয়োগ করা হয়:</p><ul><li><strong>সম্প্রদায়/গ্রাম স্বশাসন</strong>: ভেতরের সম্প্রদায় এবং গ্রামে বাসিন্দা স্বশাসন প্রয়োগ করা, এবং বাসিন্দা সম্মেলনের মাধ্যমে স্বশাসন সংস্থা নির্বাচন করা, এবং স্থানীয় জনকল্যাণের কাজ পরিচালনা করা।</li><li><strong>位面 স্বশাসন</strong>: প্রতিটি位面 সংবিধান এবং আইন মেনে চলার শর্তে, নির্দিষ্ট স্বশাসনের অধিকার রাখে, এবং স্থানীয় পরিস্থিতি অনুযায়ী বাস্তবায়নের বিস্তারিত নিয়ম তৈরি করতে পারে।</li><li><strong>প্রজাতি স্বশাসন</strong>: প্রতিটি প্রজাতির বসতি অঞ্চলে প্রজাতি স্বশাসন সংস্থা স্থাপন করা যায়, এবং নিজের প্রজাতির অভ্যন্তরীণ বিষয় পরিচালনা করা যায়, কিন্তু সংবিধান এবং আইন লঙ্ঘন করতে পারবে না।</li><li><strong>শিল্প স্বশাসন</strong>: প্রতিটি শিল্পে শিল্প সংস্থা স্থাপন করা যায়, এবং শিল্প স্ব-শৃঙ্খলা এবং শিল্প ব্যবস্থাপনা করা যায়।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>প্রশাসনিক কাঠামো এবং ক্ষমতার ভারসাম্য হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার দীর্ঘস্থায়ী শান্তি ও স্থিরতার প্রশাসনিক সুরক্ষা। &quot;তিন ক্ষমতার বিভাজন, চার ক্ষমতার ভারসাম্য&quot; এর কাঠামোর নকশা, সকল প্রজাতির অংশগ্রহণের প্রতিনিধি ব্যবস্থা, ভেতরের স্বশাসনের প্রশাসনিক মডেলের মাধ্যমে, এটি নিশ্চিত করে যে ক্ষমতা সূর্যের আলোয় চলবে, ক্ষমতার কেন্দ্রীভূতকরণ এবং লুঠের প্রশাসনের পুনর্জন্ম প্রতিরোধ করবে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য একটি স্থিতিশীল, ন্যায়বিচারপূর্ণ, দক্ষ প্রশাসনিক ব্যবস্থা প্রদান করবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>48-司法体系与裁决机制 (বিচারিক ব্যবস্থা এবং সিদ্ধান্ত প্রক্রিয়া)</li><li>03-共生文明宪章 (সিম্বায়োসিস সভ্যতার সংবিধান)</li><li>36-社会结构与阶层流动 (সামাজিক কাঠামো এবং স্তরের প্রবাহ)</li></ul>',45)])])}const c=r(o,[["render",i]]);export{b as __pageData,c as default};
